const fs = require('fs');
const path = require('path');

const assetsDir = 'W:/Games/Hanako/Work/plugins-rectify/hanako-audio-player/assets';
const files = [
  'audio-event-bus.js',
  'theme-registry.js',
  'settings-panel.js',
  'ai-theme-generator.js',
  'stage-contract.js',
  'lyrics-settings-panel.js',
  'integration.js',
];

let bundle = '// === hanako-audio-player assets bundle ===\n// Auto-generated by scripts/bundle-assets.js\n\n';

for (const f of files) {
  const filePath = path.join(assetsDir, f);
  if (!fs.existsSync(filePath)) {
    console.error(`Missing: ${filePath}`);
    process.exit(1);
  }
  const content = fs.readFileSync(filePath, 'utf-8');
  bundle += `// ── ${f} ──\n`;
  bundle += content;
  bundle += '\n\n';
}

const bundlePath = path.join(assetsDir, 'bundle.js');
fs.writeFileSync(bundlePath, bundle, 'utf-8');
console.log(`Bundle created: ${bundlePath} (${bundle.length} bytes)`);

// Delete original files
for (const f of files) {
  const filePath = path.join(assetsDir, f);
  fs.unlinkSync(filePath);
  console.log(`Deleted: ${f}`);
}
